<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_role('admin'); $title=t('Receptionist accounts'); $error=null;
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf();
    try {
        $id=(int)($_POST['id'] ?? 0); $name=required_text((string)($_POST['name'] ?? ''),'Full name'); $username=trim((string)($_POST['username'] ?? ''));
        if (!preg_match('/^[a-zA-Z0-9._-]{3,80}$/D',$username)) throw new DomainException(t('Use 3–80 letters, numbers, dots, underscores or hyphens for the username.'));
        $phone=phone_number((string)($_POST['phone'] ?? '')); $password=(string)($_POST['password'] ?? '');
        if ((!$id || $password!=='') && (strlen($password)<12 || strlen($password)>72)) throw new DomainException(t('Use a password between 12 and 72 bytes.'));
        if (one('SELECT id FROM staff_users WHERE username=? AND id<>?',[$username,$id])) throw new DomainException(t('That username is already in use.'));
        if ($id) {
            if (!one("SELECT id FROM staff_users WHERE id=? AND role='receptionist'",[$id])) throw new DomainException(t('Receptionist not found.'));
            query("UPDATE staff_users SET name=?,username=?,phone=?,active=? WHERE id=? AND role='receptionist'",[$name,$username,$phone,isset($_POST['active'])?1:0,$id]);
            if ($password!=='') query('UPDATE staff_users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$id]);
        } else query("INSERT INTO staff_users (name,username,phone,active,password_hash,role) VALUES (?,?,?,?,?,'receptionist')",[$name,$username,$phone,isset($_POST['active'])?1:0,password_hash($password,PASSWORD_DEFAULT)]);
        flash(t('Receptionist account saved.')); redirect('admin/receptionists.php');
    } catch (DomainException $e) { $error=$e->getMessage(); }
}
$edit=isset($_GET['edit'])?one("SELECT id,name,username,phone,active FROM staff_users WHERE id=? AND role='receptionist'",[(int)$_GET['edit']]):null;
if($error) $edit=array_replace($_POST,['active'=>isset($_POST['active'])?1:0]);
$users=query("SELECT id,name,username,phone,active FROM staff_users WHERE role='receptionist' ORDER BY name")->fetchAll(); require dirname(__DIR__).'/includes/header.php';
?>
<main id="main" class="container section"><div class="section-heading"><div><div class="eyebrow"><?= e(t('FRONT DESK TEAM')) ?></div><h1><?= e(t('Receptionist accounts')) ?></h1><p class="muted"><?= e(t('Give your front desk secure access to patient queues.')) ?></p></div></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?><div class="row g-4"><div class="col-lg-4"><form class="panel" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($edit['id'] ?? 0) ?>"><h2><?= e(t(!empty($edit['id'])?'Edit receptionist':'Create account')) ?></h2><?php foreach(['name'=>'Full name','username'=>'Username','phone'=>'Pakistani mobile number'] as $key=>$label): ?><label for="<?= $key ?>" class="form-label"><?= e(t($label)) ?></label><input id="<?= $key ?>" name="<?= $key ?>" class="form-control mb-3" required maxlength="<?= $key==='name'?100:($key==='phone'?20:80) ?>" value="<?= e($edit[$key] ?? '') ?>"><?php endforeach; ?><label for="password" class="form-label"><?= e(t(!empty($edit['id'])?'New password (optional)':'Password')) ?></label><input id="password" name="password" type="password" autocomplete="new-password" class="form-control" minlength="12" maxlength="72" <?= empty($edit['id'])?'required':'' ?>><p class="form-text"><?= e(t('At least 12 characters. Share securely with this staff member.')) ?></p><div class="form-check my-4"><input id="active" class="form-check-input" type="checkbox" name="active" <?= ($edit['active']??1)?'checked':'' ?>><label for="active" class="form-check-label"><?= e(t('Account is active')) ?></label></div><button class="btn btn-primary"><?= e(t('Save account')) ?></button><?php if($edit): ?><a class="btn btn-light" href="<?= e(url('admin/receptionists.php')) ?>"><?= e(t('New account')) ?></a><?php endif; ?></form></div><div class="col-lg-8"><div class="panel"><h2><?= e(t('Your reception team')) ?></h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th><?= e(t('Name')) ?></th><th><?= e(t('Username')) ?></th><th><?= e(t('Mobile')) ?></th><th><?= e(t('Status')) ?></th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['name']) ?></strong></td><td><?= e($u['username']) ?></td><td dir="ltr"><?= e($u['phone']) ?></td><td><?= status_badge($u['active']?'Active':'Inactive') ?></td><td><a href="?edit=<?= e($u['id']) ?>"><?= e(t('Edit')) ?></a></td></tr><?php endforeach; ?><?php if(!$users): ?><tr><td colspan="5" class="py-5 muted"><?= e(t('No receptionist accounts yet.')) ?></td></tr><?php endif; ?></tbody></table></div></div></div></div></main><?php require dirname(__DIR__).'/includes/footer.php'; ?>
